  [84212] = { "Di corsa col libro", "Torna al laboratorio D.E.L.T.A con il libro che cercava Jurgens.", nil, nil, nil, 0x4001a614, 0xb93dc5d0, nil, nil, nil, "..mmm" },
  [84213] = { "Fuga dallo squarcio", "Usa il Dispositivo di Comunicazione a Distanza per inviare il segnale a Jurgens, alle ⟦Tirisfal Glades=Radure di Tirisfal⟧ o alle ⟦Westfall=Marche Occidentali⟧\r\nPoi, aiutalo a dimostrare le capacità del suo trasmettitore elettrico.", nil, nil, nil, 0x24449cae, 0xbca503f9, nil, nil, nil, "..mmm" },
  [84318] = { "Ehi!", "Trova il martello scomparso di Orthas al Crocevia di Corrin.", nil, nil, nil, 0x0014e5a3, 0x4d04ade1, nil, nil, nil, "..mmm" },
  [84319] = { "Oh no, non così!", "Orthas ha bisogno che tu recuperi la sua armatura scomparsa dal cadavere di un abominio da qualche parte nella ⟦Plaguewood=Malaselva⟧.", nil, nil, nil, 0x3864f2c9, 0x0ff14544, nil, nil, nil, "..mmm" },
  [84330] = { "Un pizzico di negromanzia", "Ottieni una Runa Necrotica da ⟦Maleki the Pallid=Maleki il Pallido⟧ a Stratholme, poi trova il cadavere di Nano in decomposizione vicino alla Cripta di Zaeldarr, nel sud-ovest delle ⟦Eastern Plaguelands=Terre Infette Orientali⟧.", nil, nil, nil, 0xe2d2d338, 0x2df4d6f8, nil, nil, nil, "..mmm" },
  [84332] = { "La gratitudine di un thane", nil, nil, nil, nil, 0x365c1fc6, nil, nil, nil, nil, ".mmmm" },
  [84338] = { "Un contratto vincolante", "Consegna il ⟦Thorium Brotherhood Contract=Contratto con la Fratellanza del Torio⟧ a ⟦Lokhtos Darkbargainer=Lokhtos Pattoscuro⟧ se vuoi ricevere il progetto di Sulfuron.", "Il sottoscritto dichiara con la presente che il lingotto di Sulfuron consegnato alla ⟦Thorium Brotherhood=Fratellanza del Torio⟧ (TB Ltd.) è autentico e non una sua imitazione. Il sottoscritto riconosce inoltre che qualsiasi danno <gli/le> derivi dal tentativo di costruire, forgiare, trovare, creare, vendere o mangiare Sulfuras non è responsabilità né colpa di TB Ltd.\n\nFirmando questo contratto, accetti tutti i termini qui elencati.\n\n_________________\n\nFirma", nil, nil, 0xb3e013a8, 0xb4f357b1, 0x9f3945b5, nil, nil, "...mm", nil, nil, 0xc22a16e9, nil, nil },
  [84377] = { "La fine dell'⟦Horde=Orda⟧ Oscura", "Porta la ⟦Head of Rend Blackhand=Testa di Rend Manonera⟧ al ⟦Master Mathias Shaw=Maestro Mathias Shaw⟧ a ⟦Stormwind=Roccavento⟧.", nil, nil, nil, 0x3409b38a, 0xb41d6d2b, nil, nil, nil, "..mmm" },
