  [84414] = { "Lasciami andare per la mia strada", "Osserva Orthas mentre lascia questo mondo.", nil, nil, nil, 0x415fa18d, 0x9da87f05, nil, nil, nil, "..mmm" },
  [84495] = { "⟦Fiery Plate Gauntlets=Guanti Lunghi a Piastre Ardenti⟧", "Porta a ⟦Malyfous Darkhammer=Malyfous Martelnero⟧ 6 Lingotto di Torio Incantato, 2 ⟦Essence of Fire=Essenza di Fuoco⟧ e 4 Rubino Stellato. Dovrai anche consegnare i tuoi ⟦Unfired Plate Gauntlets=Guanti Lunghi a Piastre Compatte⟧.", "Per la barba di Thaurissan!\n\nDove li hai trovati?\n\nMa soprattutto, sei dispost<o/a> a separartene? Naturalmente ti pagherei per un gesto così nobile.\n\nFacciamo così, {name}. Se mi dai quei guanti compatti, ti insegnerò a farne un paio tutto tuo. Devi solo raccogliere i materiali per me, così potrò mettere a punto la ricetta esatta.\n\nAffare fatto??\n\nEcco la lista di ciò che mi serve. Il torio non incantato lo anticipo io, visto che i guanti li fornisci tu.", nil, nil, 0x4cbb6a5e, 0x87725cc6, 0xccc5a0a0, nil, nil, "...mm" },
  [84550] = { "⟦Codex of Defense=Codice della Difesa⟧", "Restituisci il libro ai suoi legittimi proprietari.", nil, nil, nil, 0x1bbcdca9, 0xdeb95520, nil, nil, nil, "..mmm" },
  [84555] = { "Il Compendio di Nostro", "Riporta il ⟦Nostro's Compendium of Dragon Slaying=Compendio di Nostro sull'Uccisione dei Draghi⟧ all'Ateneo.", nil, nil, nil, 0xd019ffa4, 0x30367b5a, nil, nil, nil, "..mmm" },
